#!/usr/bin/env python3
"""FS3 v205 - shields as in FreeSpace (display only), capital ship jump sound.

    Shields    A hit lights up a piece of the ship's shield mesh (from her
               POF model) round the place it struck, with the MediaVPs'
               animated shield texture in the colour of her side; it fades
               in about half a second. Fighters, bombers and the player.
               Hulls without a shield mesh get an ellipsoid. The Lucifer
               gets a bubble round her hull that glimmers at its rim while
               her shield holds. Sprites (&f3d=0) as before.
    Jump sound A capital ship's jump in or out is heard across the field
               (it fades to 75 % at the most), four at once; a fifth one
               takes the place of the oldest.

Needs v204. Edits src/12_audio.js, 40_world.js, 59_field3d.js and
60_effects.js. New model files: models_v205.zip (models/shields.json.gz,
models/shieldhit.webp).
Run assemble.py 205 afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/59_field3d.js"):
    sys.exit("Abbruch: erst v204 einspielen.")
_f = open("src/59_field3d.js", encoding="utf-8").read()
if "f3dRollMask" not in _f:
    sys.exit("Abbruch: erst v204 einspielen.")
if "f3dShieldHit" in _f:
    sys.exit("v205 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
